import sys
from functools import lru_cache

def solve():
    input_data = sys.stdin.read().split()
    idx = 0
    n, T = int(input_data[idx]), int(input_data[idx+1])
    idx += 2

    songs = []
    for i in range(n):
        t, g = int(input_data[idx]), int(input_data[idx+1])
        idx += 2
        songs.append((t, g))

    MOD = 10**9 + 7

    # Precompute sum of each mask
    mask_sum = [0] * (1 << n)
    for mask in range(1, 1 << n):
        lsb = mask & (-mask)
        bit = lsb.bit_length() - 1
        mask_sum[mask] = mask_sum[mask ^ lsb] + songs[bit][0]

    # dp[mask][last] = number of valid sequences using exactly songs in mask, ending with song `last`
    # We'll use a 2D array
    dp = [[0] * n for _ in range(1 << n)]

    # Initialize: single songs
    for i in range(n):
        if songs[i][0] <= T:
            dp[1 << i][i] = 1

    ans = 0

    # Check single songs
    for i in range(n):
        if songs[i][0] == T:
            ans = (ans + 1) % MOD

    # Fill DP
    for mask in range(1, 1 << n):
        s = mask_sum[mask]
        if s > T:
            continue
        for last in range(n):
            if not (mask & (1 << last)):
                continue
            if dp[mask][last] == 0:
                continue
            # Try to add a new song
            for nxt in range(n):
                if mask & (1 << nxt):
                    continue
                if songs[nxt][1] == songs[last][1]:
                    continue
                new_mask = mask | (1 << nxt)
                new_s = s + songs[nxt][0]
                if new_s > T:
                    continue
                dp[new_mask][nxt] = (dp[new_mask][nxt] + dp[mask][last]) % MOD
                if new_s == T:
                    ans = (ans + dp[mask][last]) % MOD

    print(ans)

solve()
